// GENERATED at build time from the geoBoundaries gbOpen dataset
// (https://www.geoboundaries.org/api/current/gbOpen/ALL/ADM1/). geoBoundaries catalogues per-country authoritative
// sources; geometries are the dataset's own simplified products,
// further Douglas-Peucker simplified (see DATA-PLAN.md). Boundaries
// come from the dataset — never hand-drawn. Downloaded 2026-11-10.
// Rings are stored delta-encoded (degrees x1000) and decoded below.
// Payload format (perf repack, 2026-11-18): the integer stream is
// zigzag-varint encoded and base64-packed into string literals instead
// of comma-separated number arrays — identical values after decode,
// but the bundle shrinks by ~half and the JS parser sees a few string
// literals instead of millions of number tokens (the arrays dominated
// cold-start parse time on phones).

function unpackInts(packed: string): number[] {
  const bin = atob(packed);
  const out: number[] = [];
  let i = 0;
  while (i < bin.length) {
    let u = 0;
    let shift = 0;
    for (;;) {
      const b = bin.charCodeAt(i++);
      u += (b & 0x7f) * 2 ** shift;
      if (!(b & 0x80)) break;
      shift += 7;
    }
    out.push(u % 2 === 0 ? u / 2 : -(u + 1) / 2);
  }
  return out;
}

function decodeRings(enc: number[]): number[][] {
  const rings: number[][] = [];
  let i = 0;
  while (i < enc.length) {
    const n = enc[i++] ?? 0;
    const ring: number[] = [];
    let l = 0;
    let a = 0;
    for (let k = 0; k < n; k++) {
      l += enc[i++] ?? 0;
      a += enc[i++] ?? 0;
      ring.push(l / 1000, a / 1000);
    }
    rings.push(ring);
  }
  return rings;
}

